import * as THREE from 'three';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.js';
import { instanceProducts, createFinish, openProductStudy } from './visual-quality.js';
import {loadPhotoProducts,openPhotoStudy} from './photo-products.js';
import {initCollaboration} from './shared-workflow.js';
import {configureStoreLighting,calibrateStoreMaterials} from './store-lighting.js';
import {loadStoreContext} from './store-context.js';
import {initStoreManager} from './store-manager.js';
import {buildGenericStore} from './generic-store.js';
import {worldPoint,planPoint,insidePolygon,fixtureContains} from './store-schema.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from './vendor/three/RoomEnvironment.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const loadLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const baseData=await fetch('./assets/data.json').then(r=>{if(!r.ok)throw Error('Data failed');return r.json()});
const baseAnchors=await fetch('./assets/anchors.json').then(r=>r.json());
let context;
try{context=await loadStoreContext(baseData,baseAnchors)}catch(e){$('#loading h3').textContent=e.message;$('#load-progress').innerHTML='<a href="/">기본 매장으로 돌아가기</a>';throw e}
const DATA=context.data,anchors=context.anchors,storeConfig=context.config;
const taskKey=context.config?'store-connect-tasks:'+context.id:'store-connect-tasks-v1';
const planKey=context.config?'store-connect-plans:'+context.id:'store-connect-plans-v1';

const products=new Map(DATA.products.map(p=>[p.product_id,p]));
const inventory=new Map(DATA.inventory.map(p=>[p.product_id,p]));
const fixtureMap=new Map(DATA.fixtures.map(f=>[f.fixture_id,f]));
let selected=storeConfig?DATA.fixtures[0].fixture_id:'C-S01',tab='display',mode='overview',comparison='proposal';
let tasks=loadLocal(taskKey,[]),plans=loadLocal(planKey,{});
const baseRows=id=>DATA.current_display.filter(r=>r.fixture_id===id).map(r=>({...r}));
const planRows=id=>plans[id]??baseRows(id);
const save=()=>{try{localStorage.setItem(taskKey,JSON.stringify(tasks));localStorage.setItem(planKey,JSON.stringify(plans));$('#task-count').textContent=tasks.length;return true}catch{toast('저장 공간이 부족합니다. 작업 보드에서 파일로 내보내세요.');return false}};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,html,kicker='STORE CONNECT'){document.exitPointerLock?.();$('#dialog-title').textContent=title;$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
const symbols={wall:'▥',cap_wall:'⌒',cap_island:'▤',shoe_wall:'↗',bag_wall:'▢',table:'▰',mannequin:'♙'};
const english={wall:'APPAREL',cap_wall:'HEADWEAR',cap_island:'HEADWEAR',shoe_wall:'FOOTWEAR',bag_wall:'BAGS',table:'DISPLAY',mannequin:'STYLING'};
$('#sku-count').textContent=DATA.inventory.filter(r=>r.carried).length;$('#task-count').textContent=tasks.length;
function renderList(){const search=$('#fixture-search').value.trim().toLowerCase();$('#fixture-list').innerHTML=DATA.fixtures.filter(f=>[f.label,f.fixture_id,...baseRows(f.fixture_id).map(r=>products.get(r.product_id)?.label)].join(' ').toLowerCase().includes(search)).map(f=>`<button class="fixture-row ${selected===f.fixture_id?'active':''}" data-fixture="${f.fixture_id}"><span class="fixture-symbol">${symbols[f.type]}</span><span><strong>${escapeHTML(f.label)}</strong><small>${f.fixture_id} · ${baseRows(f.fixture_id).length}종 진열</small></span><i class="row-dot ${f.fixture_id==='C-S01'?'alert':''}"></i></button>`).join('')||'<div class="empty">일치하는 집기가 없습니다.</div>';$$('.fixture-row').forEach(b=>b.onclick=()=>selectFixture(b.dataset.fixture,true))}
$('#fixture-search').oninput=renderList;
function selectFixture(id,focus=false){if(!fixtureMap.has(id)){toast('이 매장에 없는 집기입니다.');return}selected=id;renderList();renderInspector();$$('.hotspot').forEach(b=>b.classList.toggle('active',b.dataset.fixture===id));$('.inspector').classList.add('open');$('#breadcrumb-fixture').textContent=fixtureMap.get(id).label;if(focus)focusFixture(id);updatePlanMarkers()}
function productCard(r){const p=products.get(r.product_id),i=inventory.get(r.product_id);return `<div class="product-card"><img class="product-photo" src="${escapeHTML(p.image)}" alt="${escapeHTML(p.label)}" loading="lazy"><div class="product-info"><strong>${escapeHTML(p.label)}</strong><p>${escapeHTML(p.product_id)} · ${escapeHTML(p.color_family)}</p><div class="product-meta"><span>진열 <b>${r.quantity}</b></span><span>총 보유 <b>${i?.on_hand_qty??0}</b></span></div></div><span class="pill">${r.display_mode==='hanger'?'행거':'진열'}</span></div>`}
function renderInspector(){const f=fixtureMap.get(selected),rows=baseRows(selected);$('#fixture-name').textContent=f.label;$('#fixture-code').textContent=f.fixture_id+' · '+english[f.type];$('#fixture-kind').textContent=symbols[f.type];const alert=!storeConfig&&selected==='C-S01';$('#fixture-alert').className='fixture-alert'+(alert?'':' quiet');$('#fixture-alert').innerHTML=alert?'<span>!</span><div><strong>사진으로 확인이 필요해요</strong><p>일부 구역이 가려져 현재 상태를 확정할 수 없습니다.</p></div>':'<span>✓</span><div><strong>마지막 등록 상태입니다</strong><p>11월 7일 09:00 기준 샘플 기록입니다. 현장 검증 완료를 뜻하지 않습니다.</p></div>';if(storeConfig)$('#fixture-alert p').textContent='매장 설정에 등록한 진열입니다. 현장 완료 보고로 확인해 주세요.';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const related=DATA.work_records.filter(r=>r.fixture_ids.includes(selected));$('[data-tab="records"] span').textContent=related.length;let html='';
if(tab==='display'){html=`<div class="detail-caption"><strong>진열 상품 <b>${rows.length}</b></strong><span>${storeConfig?'매장 설정 기준':'마지막 기록 09:00'}</span></div>${rows.map(productCard).join('')}<div class="fixture-measures"><div>도면상 집기 크기<strong>${f.rect_mm[2]/1000} × ${f.rect_mm[3]/1000} m</strong></div><div>집기 상태<strong>${f.fixed===false?'이동 가능한 집기':'고정 집기'}</strong></div></div><div class="record-note">총 보유 수량에는 진열 수량이 포함됩니다.<br>3D 상품은 품목을 표현한 모델이며 개별 SKU의 정밀 복제품이 아닙니다.</div>`}
if(tab==='records'){html=`<div class="detail-caption"><strong>이 위치에 연결된 기록</strong><span>${related.length}건</span></div><div class="timeline">${related.map(r=>`<div class="timeline-item"><div class="timeline-head"><strong>${r.author_role==='store'?'매장 담당자':'본사 VMD'}</strong><time>${r.recorded_at.slice(11,16)}</time></div><p>${escapeHTML(r.message)}</p>${r.attachment_paths.length?'<span class="timeline-tag">생성한 진열 사례 연결 · 현장 촬영 아님</span>':''}</div>`).join('')||'<div class="empty">이 집기에 연결된 기록이 없습니다.</div>'}</div><div class="record-note">공간에 기록을 연결해 어떤 위치에 관한 문의인지 바로 확인합니다. 제공된 업무 대화는 출제용 샘플입니다.</div>`}
if(tab==='plan'){const rows=planRows(selected);html=`<div class="plan-controls"><button data-compare="current" class="${comparison==='current'?'active':''}">현재 등록</button><button data-compare="proposal" class="${comparison==='proposal'?'active':''}">내 변경안</button></div><p class="dialog-description">${comparison==='current'?'등록된 진열을 확인하고 있습니다.':'집기는 고정하고, 상품 구성과 수량을 검토합니다.'}</p>${(comparison==='current'?baseRows(selected):rows).map(r=>`<div class="plan-row"><span>${escapeHTML(products.get(r.product_id).label)}</span><input type="number" min="1" max="99" step="1" value="${r.quantity}" data-quantity="${r.product_id}" aria-label="${escapeHTML(products.get(r.product_id).label)} 진열 수량" ${comparison==='current'?'disabled':''}><button class="remove-product" data-remove="${r.product_id}" aria-label="변경안에서 제거" ${comparison==='current'?'disabled':''}>×</button></div>`).join('')}${comparison==='proposal'?`<select id="add-product" class="plan-input" aria-label="변경안에 상품 추가"><option value="">+ 취급 상품 추가</option>${DATA.inventory.filter(i=>i.carried&&!rows.some(r=>r.product_id===i.product_id)).map(i=>`<option value="${i.product_id}">${escapeHTML(products.get(i.product_id).label)} · 총 ${i.on_hand_qty}개</option>`).join('')}</select><div id="plan-validation"></div><button id="reset-plan" class="secondary-btn" style="margin-top:12px;width:100%">변경안 되돌리기</button>`:''}<div class="record-note">다른 집기의 진열, 예약·판매 불가 수량을 함께 계산합니다. 진열 변경에 따른 매출 효과는 이 자료만으로 예측할 수 없습니다.</div>`}
$('#detail-content').innerHTML=html;$('#create-request').innerHTML=(tab==='plan'?'변경 지시 초안 만들기':'확인 요청 만들기')+' <span>↗</span>';
if(tab==='plan'){$$('[data-compare]').forEach(b=>b.onclick=()=>{comparison=b.dataset.compare;renderInspector();updatePlanMarkers()});$$('[data-quantity]').forEach(el=>el.onchange=()=>{const value=Number(el.value);if(!Number.isInteger(value)||value<1||value>99){toast('수량은 1~99의 정수로 입력하세요.');renderInspector();return}ensurePlan();plans[selected].find(r=>r.product_id===el.dataset.quantity).quantity=value;save();renderValidation();updatePlanMarkers()});$$('[data-remove]').forEach(b=>b.onclick=()=>{ensurePlan();plans[selected]=plans[selected].filter(r=>r.product_id!==b.dataset.remove);save();renderInspector();updatePlanMarkers()});if($('#add-product'))$('#add-product').onchange=e=>{if(!e.target.value)return;ensurePlan();plans[selected].push({store_id:context.id,fixture_id:selected,product_id:e.target.value,quantity:1,display_mode:'proposal'});save();renderInspector();updatePlanMarkers()};if($('#reset-plan'))$('#reset-plan').onclick=()=>{delete plans[selected];save();renderInspector();updatePlanMarkers();toast('등록 상태로 되돌렸습니다.')};renderValidation()}}
function ensurePlan(){if(!plans[selected])plans[selected]=baseRows(selected)}
function validatePlans(){const count=new Map();for(const f of DATA.fixtures)for(const r of planRows(f.fixture_id))count.set(r.product_id,(count.get(r.product_id)||0)+r.quantity);const errors=[];for(const f of DATA.fixtures){const total=planRows(f.fixture_id).reduce((n,r)=>n+r.quantity,0);if(f.capacity&&total>f.capacity)errors.push(f.label+': 진열 한도 '+f.capacity+'개 / 변경안 '+total+'개')}for(const [id,qty]of count){const i=inventory.get(id),available=(i?.on_hand_qty??0)-(i?.customer_reserved_qty??0)-(i?.unsellable_qty??0);if(!i?.carried||qty>available)errors.push(`${products.get(id)?.label??id}: 전체 집기 ${qty}개 / 사용 가능 ${Math.max(0,available)}개`)}return errors}
function renderValidation(){if(!$('#plan-validation'))return;const errors=validatePlans();$('#plan-validation').innerHTML=`<div class="validation ${errors.length?'error':''}">${errors.length?'<strong>재고 확인이 필요합니다</strong><br>'+errors.map(escapeHTML).join('<br>'):'✓ 현재 보유·예약·판매 불가 수량 내에서 구성할 수 있습니다.'}</div>`}
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderInspector();updatePlanMarkers()});$('#close-inspector').onclick=()=>{$('.inspector').classList.remove('open');if(innerWidth>970)toast('집기를 선택하면 상세 정보를 바꿀 수 있습니다.')};
function createRequest(){const f=fixtureMap.get(selected),isPlan=tab==='plan',errors=isPlan?validatePlans():[];if(errors.length){toast('재고를 초과한 변경안을 먼저 조정하세요.');return}const proposed=planRows(selected);let body=isPlan?`${f.label}의 진열 구성을 아래와 같이 검토해 주세요.\n${proposed.map(r=>`- ${products.get(r.product_id).label}: ${r.quantity}개`).join('\n')}\n변경 후 전체와 상세 사진을 같은 위치에서 촬영해 주세요.`:selected==='C-S01'?'후면 슈즈장의 가려진 구역을 확인해 주세요.\n1. 집기 전체가 나오도록 정면에서 촬영\n2. 가려진 하단·측면을 추가 촬영\n3. 진열 상품·수량과 변경 여부를 함께 기록':'집기 전체와 상품이 보이는 사진을 촬영하고, 현재 진열 상품 및 수량이 등록 내용과 일치하는지 확인해 주세요.';
modal(isPlan?'변경 지시 초안':'현장 확인 요청',`<p class="dialog-description">집기 위치와 근거를 함께 담습니다. 초안은 이 브라우저에 저장되며 매장에 자동 전송되지 않습니다.</p><form id="request-form"><div class="form-grid"><div class="form-field"><label for="request-fixture">연결 위치</label><input id="request-fixture" value="${escapeHTML(f.label+' · '+f.fixture_id)}" readonly></div><div class="form-field"><label for="request-owner">담당자</label><input id="request-owner" value="${escapeHTML(context.name)} 담당자" maxlength="80" required></div></div><div class="form-field"><label for="request-title">제목</label><input id="request-title" value="${escapeHTML(f.label+(isPlan?' 진열 변경 검토':' 사진 및 진열 확인'))}" maxlength="140" required></div><div class="form-field"><label for="request-body">요청 내용</label><textarea id="request-body" maxlength="5000" required>${escapeHTML(body)}</textarea></div><div class="source-note">근거: ${isPlan?'현재 진열 목록 + 재고 샘플 (2026.11.07)':'위치에 연결된 업무 기록 '+(selected==='C-S01'?'WORK-C-01~04':'및 현재 진열 목록')}<br>첨부할 촬영 기준: 집기 전체 · 가려진 부분 · 상품 수량</div><div class="dialog-actions"><button type="button" id="cancel-request">취소</button><button class="primary-btn" type="submit">초안 저장 <span>↗</span></button></div></form>`,'CONNECT TO THE FIELD');$('#cancel-request').onclick=()=>$('#dialog').close();$('#request-form').onsubmit=e=>{e.preventDefault();const id=crypto.randomUUID();tasks.unshift({id,fixture:selected,title:$('#request-title').value.trim(),owner:$('#request-owner').value.trim(),body:$('#request-body').value.trim(),type:isPlan?'plan':'verify',status:'draft',created:new Date().toISOString(),proposal:isPlan?structuredClone(proposed):null});save();$('#dialog').close();toast('작업 보드에 초안을 저장했습니다.');};}
$('#create-request').onclick=createRequest;
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function showBoard(){modal('현장과 연결하는 작업 보드',`<p class="dialog-description">이 기기의 브라우저에 저장된 작업 ${tasks.length}건 · 외부 전송 없음</p>${tasks.map(t=>`<article class="task-card"><div class="task-title"><strong>${escapeHTML(t.title)}</strong><select data-status="${escapeHTML(t.id)}" aria-label="작업 상태"><option value="draft" ${t.status==='draft'?'selected':''}>초안</option><option value="requested" ${t.status==='requested'?'selected':''}>요청 기록</option><option value="review" ${t.status==='review'?'selected':''}>확인 중</option><option value="done" ${t.status==='done'?'selected':''}>검토 완료</option></select></div><small>${escapeHTML(t.fixture)} · ${escapeHTML(t.owner)} · ${new Date(t.created).toLocaleString('ko-KR')}</small><p>${escapeHTML(t.body)}</p><button class="secondary-btn" data-task-focus="${escapeHTML(t.fixture)}" style="margin-top:12px">공간에서 위치 보기 ↗</button></article>`).join('')||'<div class="empty">아직 저장된 작업이 없습니다.<br>매장 집기를 선택해 확인 요청을 만들어 보세요.</div>'}<div class="dialog-actions"><button id="export-tasks" ${tasks.length?'':'disabled'}>작업 지시 파일 내보내기 ↓</button></div>`,'FIELD WORKFLOW');$$('[data-status]').forEach(s=>s.onchange=()=>{tasks.find(t=>t.id===s.dataset.status).status=s.value;save();toast('작업 상태를 기록했습니다.')});$$('[data-task-focus]').forEach(b=>b.onclick=()=>{$('#dialog').close();selectFixture(b.dataset.taskFocus,true)});$('#export-tasks').onclick=()=>{download('STORE_CONNECT_'+context.id+'_작업지시.json',JSON.stringify({store:context.name,store_id:context.id,exported:new Date().toISOString(),tasks},null,2));toast('작업 지시 파일을 내보냈습니다.')};}
$('#board-nav').onclick=showBoard;$('#explore-nav').onclick=()=>$('#dialog').close();
function sources(showPhotos=false){modal(showPhotos?'사진에서 공간으로':'자료와 구현 기준',`${showPhotos?`<div class="source-grid"><div><img src="assets/references/tenant_2024_9.jpg" alt="MLB 명동 1층 내부 공개 참고 사진"><strong>노출 천장 · 테라조 · 진열 집기</strong><p>테넌트뉴스 · 2024.03.01 게시</p></div><div><img src="assets/references/wokard_1.jpg" alt="파란 곡선형 신발 진열 집기 참고 사진"><strong>스타디움 형태의 슈즈 디스플레이</strong><p>2024 리뉴얼 사진 · Wokard 재게시</p></div></div>`:''}<div class="source-note"><strong>공개 사진을 참고한 시각 모델 + F&F의 출제용 도면 C</strong><br>실제 지점의 실측 디지털 트윈은 아닙니다. 외곽·집기 위치는 샘플 도면, 소재·조명·진열대 형태는 공개 사진을 참고했습니다. 천장 높이·가구 세부와 일부 배치는 추정입니다. 1층을 구현했으며 계단 너머 2층은 탐색 범위에 포함되지 않습니다.</div><ul class="source-list"><li><a href="https://korea-pulse.com/myeongdong-street-walk-may-2026/" target="_blank" rel="noopener">2026.05.16 거리 방문기</a> — 최근 외관 일부 확인</li><li><a href="https://weverse.io/tws/artist/3-214275680?hl=ko" target="_blank" rel="noopener">2025.11.15 공식 Weverse 게시물</a> — 모자 선반 등 내부 디테일 확인</li><li><a href="https://tnnews.co.kr/archives/174947" target="_blank" rel="noopener">2024.03.01 테넌트뉴스</a> — 리뉴얼 공간의 전체 구조 참고</li><li><a href="${DATA.source_url}" target="_blank" rel="noopener">F&F STORE CONNECT v5.3</a> — 도면·재고·상품·업무 기록</li></ul><div class="source-note">재고와 진열은 2026.11.07 10:00 기준의 정적 샘플입니다. 실제 명동점의 현재 운영 정보가 아닙니다. 실제 사진과 생성 사례를 구분하며, 사진이 없는 구역을 검증 완료로 표시하지 않습니다.</div><div class="dialog-actions"><button id="export-model">3D 모델(GLB) 다운로드 ↓</button></div>`,'EVIDENCE & ASSUMPTIONS');$('#export-model').onclick=()=>{const a=document.createElement('a');a.href='./assets/store.glb';a.download='MLB_Myeongdong_Study.glb';a.click()}}
