function drawCustomMap(){
  const scale=Math.min(132/storeConfig.widthMm,212/storeConfig.depthMm),sx=scale,sy=scale,ox=(156-storeConfig.widthMm*scale)/2,oy=(240-storeConfig.depthMm*scale)/2,px=x=>ox+x*sx,py=y=>oy+y*sy;
  ctx.clearRect(0,0,156,240);ctx.fillStyle='#e6e9e2';ctx.strokeStyle='#a9b5aa';ctx.beginPath();storeConfig.outlineMm.forEach((p,i)=>i?ctx.lineTo(px(p[0]),py(p[1])):ctx.moveTo(px(p[0]),py(p[1])));ctx.closePath();ctx.fill();ctx.stroke();
  for(const f of storeConfig.fixtures){ctx.save();ctx.translate(px(f.xMm+f.widthMm/2),py(f.yMm+f.depthMm/2));ctx.rotate(f.rotationDeg*Math.PI/180);ctx.fillStyle=f.id===selected?'#477c64':'#bdc9bc';ctx.fillRect(-f.widthMm*sx/2,-f.depthMm*sy/2,f.widthMm*sx,f.depthMm*sy);ctx.restore()}
  const p=planPoint(storeConfig,player.x,player.z),cp=planPoint(storeConfig,camera.position.x,camera.position.z);camera.getWorldDirection(mapDirection);const target=planPoint(storeConfig,camera.position.x+mapDirection.x,camera.position.z+mapDirection.z),theta=Math.atan2((target.y-cp.y)*sy,(target.x-cp.x)*sx),half=Math.atan(Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.aspect);
  ctx.save();ctx.beginPath();ctx.rect(12,12,132,212);ctx.clip();ctx.fillStyle='#e3a63645';ctx.strokeStyle='#d09a37';ctx.beginPath();ctx.moveTo(px(cp.x),py(cp.y));ctx.arc(px(cp.x),py(cp.y),35,theta-half,theta+half);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();
  ctx.fillStyle='#235dce';ctx.strokeStyle='white';ctx.beginPath();ctx.arc(px(p.x),py(p.y),4.5,0,Math.PI*2);ctx.fill();ctx.stroke();
  ctx.save();ctx.translate(px(p.x),py(p.y));ctx.rotate(-player.yaw+storeConfig.rotationDeg*Math.PI/180);ctx.fillStyle='#1c6850';ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(-4,-7);ctx.lineTo(4,-7);ctx.closePath();ctx.fill();ctx.restore();
}
